
-- ============================================================
-- NEW TABLES FOR REYDEL TIRE DATA IMPORT
-- Run in Supabase SQL Editor
-- ============================================================

-- GL transactions (imported from QuickBooks)
CREATE TABLE IF NOT EXISTS gl_transactions (
  id UUID DEFAULT gen_random_uuid() PRIMARY KEY,
  client_id UUID ON DELETE CASCADE,
  date DATE NOT NULL,
  account TEXT NOT NULL,
  type TEXT,
  description TEXT,
  split_account TEXT,
  amount DECIMAL(12,2) NOT NULL,
  source TEXT DEFAULT 'quickbooks',
  created_at TIMESTAMP DEFAULT NOW()
);

-- Clover POS line items
CREATE TABLE IF NOT EXISTS clover_line_items (
  id UUID DEFAULT gen_random_uuid() PRIMARY KEY,
  client_id UUID ON DELETE CASCADE,
  date DATE NOT NULL,
  order_id TEXT NOT NULL,
  item_name TEXT NOT NULL,
  revenue DECIMAL(12,2) NOT NULL,
  quantity DECIMAL(8,2) DEFAULT 1,
  created_at TIMESTAMP DEFAULT NOW()
);

-- Monthly P&L summary (pre-computed for fast dashboard loads)
CREATE TABLE IF NOT EXISTS monthly_summary (
  id UUID DEFAULT gen_random_uuid() PRIMARY KEY,
  client_id UUID ON DELETE CASCADE,
  month TEXT NOT NULL,  -- YYYY-MM
  revenue DECIMAL(12,2) DEFAULT 0,
  expenses DECIMAL(12,2) DEFAULT 0,
  profit DECIMAL(12,2) DEFAULT 0,
  cogs DECIMAL(12,2) DEFAULT 0,
  gross_profit DECIMAL(12,2) DEFAULT 0,
  UNIQUE(client_id, month)
);

-- RLS
ALTER TABLE gl_transactions ENABLE ROW LEVEL SECURITY;
ALTER TABLE clover_line_items ENABLE ROW LEVEL SECURITY;
ALTER TABLE monthly_summary ENABLE ROW LEVEL SECURITY;

-- Policies (clients see their own data, admins see all)
CREATE POLICY "Clients see own gl" ON gl_transactions
  FOR SELECT USING (
    client_id = (SELECT id FROM clients WHERE email = auth.jwt()->>'email')
    OR EXISTS (SELECT 1 FROM admins WHERE email = auth.jwt()->>'email')
  );

CREATE POLICY "Clients see own clover" ON clover_line_items
  FOR SELECT USING (
    client_id = (SELECT id FROM clients WHERE email = auth.jwt()->>'email')
    OR EXISTS (SELECT 1 FROM admins WHERE email = auth.jwt()->>'email')
  );

CREATE POLICY "Clients see own summary" ON monthly_summary
  FOR SELECT USING (
    client_id = (SELECT id FROM clients WHERE email = auth.jwt()->>'email')
    OR EXISTS (SELECT 1 FROM admins WHERE email = auth.jwt()->>'email')
  );

-- Admin insert policies
CREATE POLICY "Admins insert gl" ON gl_transactions
  FOR INSERT WITH CHECK (EXISTS (SELECT 1 FROM admins WHERE email = auth.jwt()->>'email'));

CREATE POLICY "Admins insert clover" ON clover_line_items
  FOR INSERT WITH CHECK (EXISTS (SELECT 1 FROM admins WHERE email = auth.jwt()->>'email'));

CREATE POLICY "Admins insert summary" ON monthly_summary
  FOR INSERT WITH CHECK (EXISTS (SELECT 1 FROM admins WHERE email = auth.jwt()->>'email'));

CREATE POLICY "Admins update summary" ON monthly_summary
  FOR UPDATE USING (EXISTS (SELECT 1 FROM admins WHERE email = auth.jwt()->>'email'));


-- Monthly Summary Data
ON CONFLICT (client_id, month) DO UPDATE SET revenue=EXCLUDED.revenue, expenses=EXCLUDED.expenses, profit=EXCLUDED.profit, cogs=EXCLUDED.cogs, gross_profit=EXCLUDED.gross_profit;


